insert into public.country_requirement_versions(country_code,version,specification,researched_at) values('TR','2026-09-25.1','{"version":"2026-09-25.1","researchedAt":"2026-09-25","reviewMode":"document_review","countryCode":"TR","registryName":"MERSİS / Ticaret Sicili","registryUrl":"https://mersis.ticaret.gov.tr/","sources":["https://ticaret.gov.tr/ic-ticaret/ticaret-sicili/merkezi-sicil-kayit-sistemi-mersis","https://ticaret.gov.tr/ic-ticaret/sikca-sorulan-sorular/ticaret-sicili"],"fields":[{"key":"mersis","label":{"en":"MERSİS number","fr":"Numéro MERSİS"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"trade_registry_number","label":{"en":"Trade registry number","fr":"Numéro du registre du commerce"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"trade_registry_office","label":{"en":"Trade registry office","fr":"Bureau du registre du commerce"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"tax_number","label":{"en":"Corporate tax number","fr":"Numéro fiscal de la société"},"requirement":"if_applicable","appliesTo":["company"],"visibility":"private"},{"key":"tax_office","label":{"en":"Tax office","fr":"Bureau fiscal"},"requirement":"if_applicable","appliesTo":["company","sole_trader","other"],"visibility":"private"}],"evidence":{"en":"Current trade registry extract or registration document; latest relevant registry gazette notice if needed.","fr":"Extrait ou justificatif du registre du commerce à jour ; dernière annonce pertinente du registre si nécessaire."},"note":{"en":"Sole traders and other legal forms need manual review. Do not upload a personal identity number into these company fields.","fr":"Les entrepreneurs individuels et autres formes passent en revue manuelle. Ne pas saisir de numéro d’identité personnel dans les champs de société."}}'::jsonb,'2026-09-25');
insert into public.country_requirement_versions(country_code,version,specification,researched_at) values('GE','2026-09-25.1','{"version":"2026-09-25.1","researchedAt":"2026-09-25","reviewMode":"document_review","countryCode":"GE","registryName":"National Agency of Public Registry (NAPR)","registryUrl":"https://napr.gov.ge/en","sources":["https://napr.gov.ge/en/page/frequently-asked-questions","https://www.napr.gov.ge/en/page/frequently-asked-questions/economic-activity"],"fields":[{"key":"identification_code","label":{"en":"Company identification code","fr":"Code d’identification de la société"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"registration_date","label":{"en":"Registration date shown on the extract","fr":"Date d’immatriculation figurant sur l’extrait"},"requirement":"if_applicable","appliesTo":["company","sole_trader","other"],"visibility":"private"},{"key":"registered_status","label":{"en":"Status shown on the extract","fr":"Statut figurant sur l’extrait"},"requirement":"if_applicable","appliesTo":["company","sole_trader","other"],"visibility":"private"}],"evidence":{"en":"Current NAPR business registry extract identifying the entity, its registered address and representatives.","fr":"Extrait à jour du registre des entreprises NAPR identifiant l’entité, son siège et ses représentants."},"note":{"en":"Keep the registered office separate from the factory. Economic activity registration is not universally mandatory. Sole traders require private manual review.","fr":"Séparer le siège de l’usine. L’inscription au registre des activités économiques n’est pas obligatoire pour toutes les entreprises. Revue privée spécifique pour les entrepreneurs individuels."}}'::jsonb,'2026-09-25');
insert into public.country_requirement_versions(country_code,version,specification,researched_at) values('MA','2026-09-25.1','{"version":"2026-09-25.1","researchedAt":"2026-09-25","reviewMode":"document_review","countryCode":"MA","registryName":"OMPIC / Registre du commerce","registryUrl":"https://www.directinfo.ma/","sources":["https://www.ompic.ma/en/content/central-trade-register/forms","https://rbe.ompic.ma/assets/doc/Formulaire%20de%20la%20demande.pdf"],"fields":[{"key":"ice","label":{"en":"Common company identifier (ICE)","fr":"Identifiant commun de l’entreprise (ICE)"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"trade_registry_number","label":{"en":"Trade register number (RC)","fr":"Numéro du registre du commerce (RC)"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"registry_court","label":{"en":"Registry court","fr":"Tribunal du registre"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"tax_number","label":{"en":"Company tax identifier","fr":"Identifiant fiscal de la société"},"requirement":"if_applicable","appliesTo":["company"],"visibility":"private"}],"evidence":{"en":"Registration certificate or current trade register extract; confirm RC together with its registry court.","fr":"Certificat d’immatriculation ou extrait à jour du registre du commerce ; contrôler le RC avec son tribunal."},"note":{"en":"A name reservation certificate is not proof that the company is registered. The requested documents follow GSL review policy.","fr":"Un certificat négatif de réservation de nom ne prouve pas l’immatriculation. Les pièces demandées relèvent de la politique de revue GSL."}}'::jsonb,'2026-09-25');
insert into public.country_requirement_versions(country_code,version,specification,researched_at) values('TN','2026-09-25.1','{"version":"2026-09-25.1","researchedAt":"2026-09-25","reviewMode":"document_review","countryCode":"TN","registryName":"Registre national des entreprises (RNE)","registryUrl":"https://www.registre-entreprises.tn/","sources":["https://www.registre-entreprises.tn/","https://home.registre-entreprises.tn/formalites/"],"fields":[{"key":"registry_identifier","label":{"en":"Identifier shown on the RNE extract","fr":"Identifiant figurant sur l’extrait RNE"},"requirement":"review_required","appliesTo":["company"],"visibility":"private"},{"key":"tax_number","label":{"en":"Company tax identifier, if applicable","fr":"Matricule fiscal de la société, le cas échéant"},"requirement":"if_applicable","appliesTo":["company"],"visibility":"private"}],"evidence":{"en":"Current RNE extract; use the official extract authenticity verification service.","fr":"Extrait RNE à jour ; utiliser le service officiel de vérification de l’authenticité de l’extrait."},"note":{"en":"Preserve the identifier exactly as printed. Do not infer a tax or VAT status from registration alone.","fr":"Conserver l’identifiant tel qu’il figure sur l’extrait. Ne pas déduire un statut fiscal ou de TVA de la seule immatriculation."}}'::jsonb,'2026-09-25');
insert into public.country_requirement_versions(country_code,version,specification,researched_at) values('FR','2026-09-25.1','{"version":"2026-09-25.1","researchedAt":"2026-09-25","reviewMode":"document_review","countryCode":"FR","registryName":"RNE / INPI","registryUrl":"https://data.inpi.fr/","sources":["https://entreprendre.service-public.gouv.fr/vosdroits/R19859","https://www.entreprises.gouv.fr/la-dge/actualites/attestation-dimmatriculation-au-registre-national-des-entreprises-ou-extrait-rne"],"fields":[{"key":"siren","label":{"en":"SIREN — company identifier","fr":"SIREN — identifiant de l’entreprise"},"requirement":"review_required","appliesTo":["company","sole_trader","other"],"visibility":"private"},{"key":"headquarters_siret","label":{"en":"Registered office SIRET","fr":"SIRET de l’établissement siège"},"requirement":"if_applicable","appliesTo":["company","sole_trader","other"],"visibility":"private"},{"key":"vat_number","label":{"en":"VAT number, if applicable","fr":"Numéro de TVA, si applicable"},"requirement":"if_applicable","appliesTo":["company","sole_trader","other"],"visibility":"private"}],"evidence":{"en":"RNE registration attestation; a current Kbis may also be provided where applicable.","fr":"Attestation d’immatriculation au RNE ; un extrait Kbis à jour peut également être fourni si applicable."},"note":{"en":"The SIREN identifies the entity; each establishment has its own SIRET. VAT eligibility needs a separate check.","fr":"Le SIREN identifie l’entité ; chaque établissement possède son SIRET. Le statut TVA nécessite un contrôle distinct."}}'::jsonb,'2026-09-25');
